#include <x86intrin.h>
#include <cstdint>

// Calibrate once: cycles per nanosecond (TSC is invariant on modern x86).
extern double g_cycles_per_ns;   // e.g., 3.0 on a 3 GHz box

struct ScopedTsc {
    uint64_t start;
    ScopedTsc() { unsigned aux; start = __rdtscp(&aux); }  // serializing-ish read
    uint64_t elapsed_ns() const {
        unsigned aux; uint64_t end = __rdtscp(&aux);
        _mm_lfence();                      // keep the read inside the region
        return (uint64_t)((end - start) / g_cycles_per_ns);
    }
};

// Hot path: time a region, record into a histogram, NO alloc/lock/IO inline.
extern void hist_record(uint64_t ns);   // O(1), pre-allocated buckets

void on_event(const Event& e) {
    ScopedTsc t;
    handle(e);                            // the work we want to measure
    hist_record(t.elapsed_ns());          // cheap bucket bump
}

// Sketch of a fixed-bucket latency histogram (HdrHistogram-style idea).
#include <array>
#include <cstdint>
#include <cmath>

struct LatencyHist {
    static constexpr int N = 1 << 16;     // bucket per ~log step
    std::array<uint64_t, N> buckets{};
    uint64_t count = 0, maxv = 0;

    static int bucket_of(uint64_t ns) {   // coarse log bucketing
        return ns == 0 ? 0 : std::min(N - 1, (int)(std::log2((double)ns) * 1024));
    }
    void record(uint64_t ns) {            // O(1), allocation-free
        ++buckets[bucket_of(ns)]; ++count; if (ns > maxv) maxv = ns;
    }
    uint64_t percentile(double p) const { // walk buckets to the p-th sample
        uint64_t target = (uint64_t)(p / 100.0 * count), seen = 0;
        for (int i = 0; i < N; ++i) { seen += buckets[i]; if (seen >= target) return 1ull << (i / 1024); }
        return maxv;
    }
    // report: p50=percentile(50), p99=..(99), p999=..(99.9), max=maxv
};
// Prefer the real HdrHistogram in production; this shows the principle.

void strategy_loop(LatencyHist& hist) {
    Event e;
    while (running) {
        if (!q.pop(e)) { _mm_pause(); continue; }
        unsigned a;
        uint64_t t0 = __rdtscp(&a);
        handle(e);                                  // measured work
        uint64_t t1 = __rdtscp(&a); _mm_lfence();
        hist.record((uint64_t)((t1 - t0) / g_cycles_per_ns)); // O(1), no alloc/lock
    }
}
